<?php
require __DIR__.'/app.php';require_roles(['owner','company_manager','branch_manager']);$currentRole=current_role();$shopId=(int)$_SESSION['shop_id'];$allowedRoles=match($currentRole){'owner'=>['company_manager','branch_manager','employee'],'company_manager'=>['branch_manager','employee'],'branch_manager'=>['employee']};$formError='';
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){verify_csrf();$emailAddress=strtolower(trim((string)($_POST['email']??'')));$temporaryPassword=(string)($_POST['password']??'');$newUserRole=(string)($_POST['role']??'');$branchId=null;if(in_array($newUserRole,['employee','branch_manager'],true)){$submittedBranchId=filter_var($_POST['branch_id']??null,FILTER_VALIDATE_INT);if(!$submittedBranchId||!validate_branch($submittedBranchId))$formError='يجب اختيار فرع ضمن صلاحياتك.';else $branchId=$submittedBranchId;}if(!$formError&&(!filter_var($emailAddress,FILTER_VALIDATE_EMAIL)||strlen($temporaryPassword)<12||!in_array($newUserRole,$allowedRoles,true)))$formError='تحقق من البريد وكلمة المرور والدور المسموح.';if(!$formError){try{$userStatement=db()->prepare('INSERT INTO users(shop_id,branch_id,email,password_hash,role) VALUES(?,?,?,?,?)');$userStatement->execute([$shopId,$branchId,$emailAddress,password_hash($temporaryPassword,PASSWORD_DEFAULT),$newUserRole]);header('Location: users.php?created=1');exit;}catch(PDOException $databaseError){$formError='تعذر إنشاء الحساب؛ قد يكون البريد مستخدمًا.';}}}
if($currentRole==='branch_manager'){$userStatement=db()->prepare('SELECT id,name FROM branches WHERE shop_id=? AND id=?');$userStatement->execute([$shopId,(int)$_SESSION['branch_id']]);}else{$userStatement=db()->prepare('SELECT id,name FROM branches WHERE shop_id=? ORDER BY name');$userStatement->execute([$shopId]);}$branchOptions=$userStatement->fetchAll();
if($currentRole==='branch_manager'){$userStatement=db()->prepare("SELECT email,role,created_at FROM users WHERE shop_id=? AND branch_id=? AND role='employee'");$userStatement->execute([$shopId,(int)$_SESSION['branch_id']]);}else{$userStatement=db()->prepare('SELECT email,role,created_at FROM users WHERE shop_id=? ORDER BY role,email');$userStatement->execute([$shopId]);}$userRecords=$userStatement->fetchAll();
page_start('المستخدمون والصلاحيات');if(isset($_GET['created']))echo '<p class="success">تم إنشاء المستخدم.</p>';if($formError)echo '<p class="alert">'.e($formError).'</p>';echo '<section class="card"><h2>إضافة حساب</h2><form method="post">'.csrf_field().'<div class="grid"><label>البريد الإلكتروني<input type="email" name="email" required maxlength="254"></label><label>كلمة مرور مؤقتة (12 حرفًا على الأقل)<input type="password" name="password" minlength="12" required></label><label>الدور<select name="role">';foreach($allowedRoles as $roleOption)echo '<option value="'.e($roleOption).'">'.e(ROLE_LABELS[$roleOption]).'</option>';echo '</select></label><label>الفرع<select name="branch_id"><option value="">اختر عند الحاجة</option>';foreach($branchOptions as $branchOption)echo '<option value="'.(int)$branchOption['id'].'">'.e($branchOption['name']).'</option>';echo '</select></label></div><button>إنشاء الحساب</button></form></section><section class="card table-wrap"><h2>الحسابات الحالية</h2><table><thead><tr><th>البريد</th><th>الدور</th><th>تاريخ الإنشاء</th></tr></thead><tbody>';foreach($userRecords as $userRecord)echo '<tr><td>'.e($userRecord['email']).'</td><td>'.e(ROLE_LABELS[$userRecord['role']]??$userRecord['role']).'</td><td>'.e($userRecord['created_at']).'</td></tr>';if(!$userRecords)echo '<tr><td colspan="3">لا توجد حسابات إضافية.</td></tr>';echo '</tbody></table></section>';page_end();

